import React from "react"

import styled, { ThemeProvider } from "styled-components"

import NavBar from "~/src/components/navBar/navBar"
import useSiteMetadata from "~/src/hooks/useSiteMetadata"
import useTheme from "~/src/hooks/useTheme"
import ThemeContext from "~/src/stores/themeContext"
import GlobalStyle from "~/src/styles/globalStyle"
import styledTheme from "~/src/styles/styledTheme"

// import packageJSON from "../../package.json"

// const { name, homepage } = packageJSON

const Layout: React.FC<React.PropsWithChildren> = ({ children }) => {
  const { theme, themeToggler } = useTheme()
  const { title, author } = useSiteMetadata()
  const copyrightString = `© 2026 ${author}.  All rights reserved.`

  return (
    <ThemeProvider theme={styledTheme}>
      <ThemeContext.Provider value={theme}>
        <GlobalStyle />
        <Container>
          <NavBar title={title} themeToggler={themeToggler} />
          <div className="box">{children}</div>
        </Container>
        <Footer role="contentinfo">
          <Copyright aria-label="Copyright">{copyrightString}</Copyright>
        </Footer>
      </ThemeContext.Provider>
    </ThemeProvider>
  )
}

const Container = styled.div`
  width: 100%;
  height: 100%;
  min-height: calc(100vh - var(--footer-height));
  background-color: var(--color-post-background);

  @media (min-width: ${({ theme }) => theme.device.sm}) {
    div.box {
      display: flex;
      aside {
        // background-color: yellow;
        flex: 1 0 auto;
      }
    }
  }
`

const Footer = styled.footer`
  display: flex;
  flex-direction: column;
  text-align: center;
  justify-content: center;
  align-items: center;
  height: var(--footer-height);
  background-color: var(--color-gray-1);
`

const Copyright = styled.p`
  font-size: var(--text-sm);
  font-weight: var(--font-weight-regular);
  color: var(--color-gray-6);
`

// const RepoLink = styled.a`
//   color: var(--color-blue);
//   &:hover {
//     text-decoration: underline;
//   }
// `

export default Layout
